'use strict';

// MODULES //

var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var ndarraylike2scalar = require( '@stdlib/ndarray/base/ndarraylike2scalar' );
var strided = require( '@stdlib/blas/ext/base/dreplicate' ).ndarray;


// MAIN //

/**
* Replicates each element in a one-dimensional double-precision floating-point ndarray a specified number of times.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a one-dimensional output ndarray. Must have `N * k` elements, where `N` is the number of elements in the input ndarray, and `k` is the number of times to replicate each element.
*     -   a zero-dimensional ndarray specifying the number of times to replicate each element.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {ndarray} output ndarray
*
* @example
* var Float64Vector = require( '@stdlib/ndarray/vector/float64' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
* var zeros = require( '@stdlib/ndarray/zeros' );
*
* var x = new Float64Vector( [ 1.0, 2.0, 3.0 ] );
* var out = zeros( [ 6 ], {
*     'dtype': 'float64'
* });
*
* var k = scalar2ndarray( 2, {
*     'dtype': 'generic'
* });
*
* var v = dreplicate( [ x, out, k ] );
* // returns <ndarray>[ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0 ]
*
* var bool = ( v === out );
* // returns true
*/
function dreplicate( arrays ) {
	var out;
	var x;
	var k;

	x = arrays[ 0 ];
	out = arrays[ 1 ];
	k = ndarraylike2scalar( arrays[ 2 ] );

	strided( numelDimension( x, 0 ), k, getData( x ), getStride( x, 0 ), getOffset( x ), getData( out ), getStride( out, 0 ), getOffset( out ) ); // eslint-disable-line max-len
	return out;
}


// EXPORTS //

module.exports = dreplicate;

